require(script.Parent.Parent.Parent.Parent.Parent:WaitForChild(".luau-aliases"):WaitForChild("@jsdotlua"):WaitForChild("es7-types"))
return function(list, callback, p)
	local count = #list
	local v = 1

	while v <= count do
		local v2 = list[v]

		if p == nil then
			callback(v2, v, list)
		else
			callback(p, v2, v, list)
		end

		count = #list < count and #list or count
		v += 1
	end
end